export const SPORTS={bike:{name:'Alp-Mountainbike-Park',season:'Sommer',maxSpeed:16,width:3.4,accel:2.7,jump:5.2},sled:{name:'Winter-Wunderland-Rodelbahn',season:'Winter',maxSpeed:18,width:3.7,accel:3.1,jump:3.4}};
export const RIDE_ENTRY={x:-4,z:-.2};
export const FINISH=480;
export const trackCenter=d=>4*Math.sin(d*.025)+2*Math.sin(d*.011);
export const rampLift=d=>{let y=0;for(const lip of RIDE_RAMPS){const t=d-lip;if(t>=-9&&t<=0)y+=1.5*((t+9)/9)**2;else if(t>0&&t<=8)y+=1.5;else if(t>8&&t<23){const u=(t-8)/15;y+=1.5*(1-u*u*(3-2*u));}}return y;};
export const rideHeight=(x,d)=>-d*.18+.22*Math.sin(d*.06)+Math.max(0,Math.abs(x-trackCenter(d))-7)**2*.018+rampLift(d)*Math.max(0,Math.min(1,(3-Math.abs(x-trackCenter(d)))/.9));
export const RIDE_GATES=Array.from({length:7},(_,i)=>60+i*60);
export const RIDE_OBSTACLES=[{d:95,offset:-.8},{d:185,offset:1.0},{d:270,offset:-.9},{d:370,offset:.9}];
export const RIDE_RAMPS=[135,235,310,405];
export const freshRides=()=>({bike:{runs:0,best:0},sled:{runs:0,best:0},active:null});
const n=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b;
export function validRides(r){if(!r||!['bike','sled'].every(k=>r[k]&&Number.isSafeInteger(r[k].runs)&&r[k].runs>=0&&r[k].runs<=1000000&&Number.isSafeInteger(r[k].best)&&r[k].best>=0&&r[k].best<=1000))return false;const c=r.active;return c===null||!!c&&Object.hasOwn(SPORTS,c.mode)&&n(c.distance,0,FINISH)&&n(c.x,-30,30)&&n(c.speed,0,18)&&n(c.heading,-.7,.7)&&n(c.air,0,8)&&n(c.vy,-20,10)&&n(c.time,0,7200)&&n(c.countdown,0,3)&&n(c.cooldown,0,3)&&n(c.jumpCooldown,0,2)&&Number.isSafeInteger(c.crashes)&&n(c.crashes,0,10000)&&Number.isSafeInteger(c.jumps)&&n(c.jumps,0,10000)&&Array.isArray(c.gates)&&c.gates.length===RIDE_GATES.filter(d=>d<=c.distance).length&&c.gates.every(v=>typeof v==='boolean')&&typeof c.done==='boolean'&&c.done===(c.distance===FINISH);}
export function startDescent(s,mode){if(!Object.hasOwn(SPORTS,mode)||s.position.region!=='alp'||s.position.inside||Math.hypot(s.position.x-RIDE_ENTRY.x,s.position.z-RIDE_ENTRY.z)>3)return{ok:false,message:'Bike und Schlitten stehen im Unterstand neben der Alphütte.'};if(s.activities.active)return{ok:false,message:'Beende zuerst das laufende Minispiel.'};if(s.activities.rides.active)return{ok:false,message:'Setze die gespeicherte Abfahrt fort oder beende sie zuerst.'};if(s.energy<8)return{ok:false,message:'Du brauchst acht Energie für die Abfahrt.'};s.energy-=8;s.activities.rides.active={mode,x:0,distance:0,speed:0,heading:0,air:0,vy:0,time:0,countdown:3,cooldown:0,jumpCooldown:0,crashes:0,jumps:0,gates:[],done:false};return{ok:true};}
export function stepDescent(c,dt,{steer=0,brake=false,jump=false}={}){if(!c||c.done||!n(dt,0,.1)||!Number.isFinite(steer))return null;if(c.countdown>0){c.countdown=Math.max(0,c.countdown-dt);return null;}const mode=SPORTS[c.mode],old=c.distance;let event=null;c.time+=dt;c.cooldown=Math.max(0,c.cooldown-dt);c.jumpCooldown=Math.max(0,c.jumpCooldown-dt);c.heading+=(Math.max(-1,Math.min(1,steer))*.6-c.heading)*Math.min(1,dt*(c.mode==='bike'?5:3.5));c.speed=Math.max(0,Math.min(mode.maxSpeed,c.speed+(mode.accel-c.speed*.075-(brake?9:0))*dt));
 if(jump&&c.air<=.001&&c.jumpCooldown===0){c.vy=mode.jump;c.jumpCooldown=.8;c.jumps++;event={type:'jump'};}c.vy-=9.8*dt;c.air=Math.max(0,c.air+c.vy*dt);if(c.air===0)c.vy=0;c.distance=Math.min(FINISH,c.distance+c.speed*Math.cos(c.heading)*dt);c.x=Math.max(-30,Math.min(30,c.x+Math.sin(c.heading)*c.speed*dt));const off=Math.abs(c.x-trackCenter(c.distance));
 function crash(){if(c.cooldown>0)return;c.crashes++;c.speed*=.35;c.cooldown=1.3;event={type:'crash'};}
 if(off>mode.width){c.speed=Math.max(brake?0:1,c.speed-dt*5);if(off>mode.width+2){crash();c.x=trackCenter(c.distance)+Math.sign(c.x-trackCenter(c.distance))*(mode.width+.8);}}
 for(const o of RIDE_OBSTACLES)if(old<o.d&&c.distance>=o.d&&Math.abs(c.x-trackCenter(o.d)-o.offset)<.75&&c.air<.48)crash();for(const d of RIDE_RAMPS)if(old<d&&c.distance>=d&&Math.abs(c.x-trackCenter(d))<1.6&&c.speed>6&&c.air<.1){c.vy=mode.jump+1;c.jumps++;event={type:'ramp'};}
 while(c.gates.length<RIDE_GATES.length&&c.distance>=RIDE_GATES[c.gates.length]){const hit=Math.abs(c.x-trackCenter(RIDE_GATES[c.gates.length]))<mode.width-.4;c.gates.push(hit);event={type:hit?'gate':'miss'};}
 if(c.distance===FINISH){c.done=true;return{type:'finish'};}return event;}
export function descentScore(c){return Math.max(0,Math.min(1000,Math.round(c.gates.filter(Boolean).length/7*700+Math.min(100,c.jumps*25)+Math.max(0,200-c.time*1.3)-c.crashes*55)));}
export function finishDescent(s){const c=s.activities.rides.active;if(!c?.done)return{ok:false,message:'Die Abfahrt läuft noch.'};const score=descentScore(c),record=s.activities.rides[c.mode];record.runs=Math.min(1000000,record.runs+1);record.best=Math.max(record.best,score);s.energy=Math.max(0,s.energy-Math.min(20,c.crashes*2));s.activities.rides.active=null;return{ok:true,score,time:c.time,crashes:c.crashes,mode:c.mode,message:score>=550?'Saubere Abfahrt!':'Im Ziel! Übe die Kurvenlinie und bremse vor Hindernissen.'};}
